215	    /**
216	     * The owner's Luhn check digit: a single digit ({@code 0}-{@code 9}) computed with the
217	     * standard Luhn algorithm over the decimal digits contained in the {@code customerCode}
218	     * (non-digit characters are ignored).
219	     *
220	     * @return the Luhn check digit, or {@code null} if the customer code has not been assigned
221	     */
222	    public Integer getCheckDigit() {
223	        if (this.customerCode == null) {
224	            return null;
225	        }
226	        int sum = 0;
227	        boolean dbl = true;
228	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
229	            char c = this.customerCode.charAt(i);
230	            if (c < '0' || c > '9') {
