328	     * absent, not a 4-digit number, or in no known range.
329	     *
330	     * @param postcode the owner's postcode (may be {@code null})
331	     * @return the matching region, or {@code null}
332	     */
333	    private static String regionForPostcode(String postcode) {
334	        if (postcode == null || !postcode.matches("\\d{4}")) {
335	            return null;
336	        }
337	        int value = Integer.parseInt(postcode);
338	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
339	            int[] range = entry.getValue();
340	            if (value >= range[0] && value <= range[1]) {
341	                return entry.getKey();
342	            }
343	        }
344	        return null;
345	    }
346	
347	    protected Set<Pet> getPetsInternal() {
348	        if (this.pets == null) {
349	            this.pets = new HashSet<>();
350	        }
351	        return this.pets;
352	    }
353	
354	    protected void setPetsInternal(Set<Pet> pets) {
355	        this.pets = pets;
356	    }
