358	    public List<Pet> getPets() {
359	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
360	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
361	        return Collections.unmodifiableList(sortedPets);
362	    }
363	
364	    public void setPets(List<Pet> pets) {
365	        this.pets = new HashSet<>(pets);
366	    }
367	
368	    public void addPet(Pet pet) {
369	        getPetsInternal().add(pet);
370	        pet.setOwner(this);
371	    }
372	
373	    /**
374	     * Return the Pet with the given name, or null if none found for this Owner.
375	     *
376	     * @param name to test
377	     * @return true if pet name is already in use
378	     */
379	    public Pet getPet(String name) {
380	        return getPet(name, false);
381	    }
382	
383	    /**
384	     * Return the Pet with the given name, or null if none found for this Owner.
385	     *
386	     * @param name to test
387	     * @return true if pet name is already in use
388	     */
389	    public Pet getPet(String name, boolean ignoreNew) {
390	        name = name.toLowerCase();
391	        for (Pet pet : getPetsInternal()) {
392	            if (!ignoreNew || !pet.isNew()) {
393	                String compName = pet.getName();
394	                compName = compName.toLowerCase();
395	                if (compName.equals(name)) {
396	                    return pet;
397	                }
398	            }
399	        }
400	        return null;
401	    }
402	
403	    public Pet getPet(Integer petId) {
404	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
405	    }
406	
407	    @Override
408	    public String toString() {
409	        return new ToStringCreator(this)
410	
411	            .append("id", this.getId())
412	            .append("new", this.isNew())
413	            .append("lastName", this.getLastName())
414	            .append("firstName", this.getFirstName())
415	            .append("address", this.address)
416	            .append("city", this.city)
417	            .append("telephone", this.telephone)
418	            .append("email", this.email)
419	            .toString();
420	    }
421	}
