58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
69	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
70	     */
71	    /**
72	     * Dedicated audit logger. Successful side-effects (e.g. owner creation) are recorded here so
73	     * they can be routed and asserted independently of the application's diagnostic logging.
74	     */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    private static final Pattern EMAIL_PATTERN =
78	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
79	
80	    /**
81	     * Common address abbreviations expanded to their full form during address normalization.
82	     * Matching is performed per whitespace-separated token on the upper-cased value.
83	     */
84	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
85	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
86	
87	    /**
88	     * Required national-number length (the digits after the country code) per E.164 country code.
89	     * A number whose country code appears here must carry exactly the mapped number of national
90	     * digits; country codes not listed fall back to the generic 8-to-15 total-digit rule.
91	     */
92	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
93	        Map.of("61", 9, "1", 10);
94	
95	    /**
96	     * Inclusive 4-digit postcode range {@code {low, high}} per region, the fixed ground truth for
97	     * validating an owner's postcode against the region derived from its city. A region not listed
98	     * here (e.g. the {@code "UNKNOWN"} locality of an unmapped city) imposes no range constraint, so
99	     * any 4-digit postcode is accepted.
100	     */
101	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
102	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
103	
104	    private final ClinicService clinicService;
105	
106	    private final OwnerMapper ownerMapper;
107	
108	    private final PetMapper petMapper;
109	
110	    private final VisitMapper visitMapper;
111	
112	    public OwnerRestControllerV1(ClinicService clinicService,
113	                                 OwnerMapper ownerMapper,
114	                                 PetMapper petMapper,
115	                                 VisitMapper visitMapper) {
116	        this.clinicService = clinicService;
117	        this.ownerMapper = ownerMapper;
118	        this.petMapper = petMapper;
119	        this.visitMapper = visitMapper;
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
125	        Collection<Owner> owners;
126	        if (lastName != null) {
127	            owners = this.clinicService.findOwnerByLastName(lastName);
128	        } else {
129	            owners = this.clinicService.findAllOwners();
130	        }
131	        if (owners.isEmpty()) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
140	        Owner owner = this.clinicService.findOwnerById(ownerId);
141	        if (owner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
150	        HttpHeaders headers = new HttpHeaders();
151	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
152	        LocalDate suppliedDate = owner.getRegistrationDate();
153	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
154	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
155	        }
156	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
157	        LocalDate registrationDate = toBusinessDay(effectiveDate);
158	        owner.setRegistrationDate(registrationDate);
159	        long createdToday = this.clinicService.findAllOwners().stream()
160	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
161	            .count();
162	        if (createdToday >= 100) {
163	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
164	        }
165	        owner.setBulkSignupWarning(createdToday > 80);
166	        String address = normalizeAddress(owner.getAddress());
167	        if (address == null || address.isEmpty()) {
168	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
169	        }
170	        owner.setAddress(address);
171	        String telephone = toE164(owner.getTelephone());
172	        if (telephone == null) {
173	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
174	        }
175	        owner.setTelephone(telephone);
176	        if (owner.getEmail() != null) {
177	            String email = normalizeEmail(owner.getEmail());
178	            if (!EMAIL_PATTERN.matcher(email).matches()) {
179	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
180	            }
181	            owner.setEmail(email);
182	        }
183	        if (!isPostcodeValidForCity(owner.getPostcode(), owner.getLocality())) {
184	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
185	        }
186	        String cityKey = householdKey(owner.getCity());
187	        long cityCount = this.clinicService.findAllOwners().stream()
188	            .filter(existing -> existing.getCity() != null
189	                && cityKey.equals(householdKey(existing.getCity())))
190	            .count();
191	        if (cityCount >= 50) {
192	            return new ResponseEntity<>(HttpStatus.CONFLICT);
193	        }
194	        String lastNameKey = householdKey(owner.getLastName());
195	        String addressKey = householdKey(owner.getAddress());
196	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
197	            .filter(existing -> lastNameKey.equals(householdKey(existing.getLastName()))
198	                && addressKey.equals(householdKey(existing.getAddress())))
199	            .toList();
200	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
201	        if (sharesHousehold) {
202	            String householdId = householdMembers.stream()
203	                .map(Owner::getHouseholdId)
204	                .filter(Objects::nonNull)
205	                .findFirst()
206	                .orElseGet(() -> householdId(owner));
207	            owner.setHouseholdId(householdId);
208	            owner.setHouseholdSize(householdMembers.size() + 1);
209	        } else {
210	            owner.setHouseholdSize(1);
211	        }
212	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
213	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
214	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
215	        // telephone is part of the key, two household members with different telephones are allowed.
216	        String identityKey = owner.getIdentityKey();
217	        boolean identityInUse = this.clinicService.findAllOwners().stream()
218	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
219	        if (identityInUse) {
220	            return new ResponseEntity<>(HttpStatus.CONFLICT);
221	        }
222	        if (sharesHousehold) {
223	            for (Owner member : householdMembers) {
224	                if (member.getHouseholdId() == null) {
225	                    member.setHouseholdId(owner.getHouseholdId());
226	                    this.clinicService.saveOwner(member);
227	                }
228	            }
229	        }
230	        owner.setCustomerCode(customerCode(owner));
231	        String firstNameKey = householdKey(owner.getFirstName());
232	        String namesakeLastNameKey = householdKey(owner.getLastName());
233	        long namesakeCount = this.clinicService.findAllOwners().stream()
234	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
235	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
236	            .count();
237	        owner.setNamesakeCount((int) namesakeCount);
238	        this.clinicService.saveOwner(owner);
239	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
240	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
241	            owner.getMembershipLevel());
242	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
243	        headers.setLocation(UriComponentsBuilder.newInstance()
244	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
245	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
246	    }
247	
248	    /**
249	     * Validates an owner's postcode against the region derived from its city. The postcode is
250	     * optional: a {@code null} value is always accepted. When present it must fall within the
251	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
252	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
253	     * The 4-digit syntax itself is enforced upstream by bean validation.
254	     *
255	     * @param postcode the owner's postcode (may be {@code null})
256	     * @param locality the region derived from the owner's city
257	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
258	     *         within the region's range; {@code false} when it is out of range
259	     */
260	    private boolean isPostcodeValidForCity(String postcode, String locality) {
261	        if (postcode == null) {
262	            return true;
263	        }
264	        int[] range = REGION_POSTCODES.get(locality);
265	        if (range == null) {
266	            return true;
267	        }
268	        int value = Integer.parseInt(postcode);
269	        return value >= range[0] && value <= range[1];
270	    }
271	
272	    /**
273	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
274	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
275	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
276	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
277	     * recognised country codes the national number (the digits after the country code) must also be
278	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
279	     * needs 10); a wrong national-number length yields {@code null}.
280	     *
281	     * @param telephone the raw telephone value (may be {@code null})
282	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
283	     *         a valid E.164 number
284	     */
285	    private String toE164(String telephone) {
286	        if (telephone == null) {
287	            return null;
288	        }
289	        String trimmed = telephone.trim();
290	        boolean hasCountryCode = trimmed.startsWith("+");
291	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
292	        if (hasCountryCode) {
293	            cleaned = cleaned.substring(1);
294	        }
295	        if (!cleaned.matches("[0-9]+")) {
296	            return null;
297	        }
298	        String digits;
299	        if (hasCountryCode) {
300	            digits = cleaned;
301	        } else {
302	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
303	            digits = "61" + national;
304	        }
305	        if (digits.length() < 8 || digits.length() > 15) {
306	            return null;
307	        }
308	        if (!hasValidNationalNumberLength(digits)) {
309	            return null;
310	        }
311	        return "+" + digits;
312	    }
313	
314	    /**
315	     * Checks the national-number length of an E.164 digit string (country code plus national
316	     * number, without the leading {@code '+'}) against its country code. When the number's country
317	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
318	     * country code must number exactly what that country requires; the longest matching country
319	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
320	     * only by the generic total-length rule).
321	     *
322	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
323	     * @return {@code true} if the national-number length is acceptable for the country code
324	     */
325	    private boolean hasValidNationalNumberLength(String digits) {
326	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
327	            .filter(entry -> digits.startsWith(entry.getKey()))
328	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
329	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
330	            .orElse(true);
331	    }
332	
333	    /**
334	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
335	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
336	     *
337	     * @param email the raw email value (must not be {@code null})
338	     * @return the trimmed, lower-cased email
339	     */
340	    private String normalizeEmail(String email) {
341	        return email.trim().toLowerCase(Locale.ROOT);
342	    }
343	
344	    /**
345	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
346	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
347	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
348	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
349	     * normalized form, and every household comparison uses it.
350	     *
351	     * @param address the raw address value (may be {@code null})
352	     * @return the normalized address, or {@code null} if the input was {@code null}
353	     */
354	    private String normalizeAddress(String address) {
355	        if (address == null) {
356	            return null;
357	        }
358	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
359	        if (collapsed.isEmpty()) {
360	            return collapsed;
361	        }
362	        String[] tokens = collapsed.split(" ");
363	        StringBuilder sb = new StringBuilder(collapsed.length());
364	        for (int i = 0; i < tokens.length; i++) {
365	            if (i > 0) {
366	                sb.append(' ');
367	            }
368	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
369	        }
370	        return sb.toString();
371	    }
372	
373	    /**
374	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
375	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
376	     * so that owners are compared case-insensitively with collapsed whitespace.
377	     *
378	     * @param value the raw value (must not be {@code null})
379	     * @return the normalized comparison key
380	     */
381	    private String householdKey(String value) {
382	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
383	    }
384	
385	    /**
386	     * Derives a stable, shared household identifier for the owner's household. The value is a
387	     * deterministic function of the normalized last name and address ({@link #householdKey}), so
388	     * every owner in the same household derives the identical identifier of the form
389	     * {@code 'HH-<12 upper-case hex>'}.
390	     *
391	     * @param owner the owner whose household identifier is derived
392	     * @return the stable household identifier
393	     */
394	    private String householdId(Owner owner) {
395	        String key = householdKey(owner.getLastName()) + "|" + householdKey(owner.getAddress());
396	        try {
397	            byte[] digest = MessageDigest.getInstance("SHA-256")
398	                .digest(key.getBytes(StandardCharsets.UTF_8));
399	            StringBuilder sb = new StringBuilder(digest.length * 2);
400	            for (byte b : digest) {
401	                sb.append(String.format("%02x", b));
402	            }
403	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
404	        }
405	        catch (java.security.NoSuchAlgorithmException e) {
406	            throw new IllegalStateException("SHA-256 not available", e);
407	        }
408	    }
409	
410	    /**
411	     * Builds the customer code for a newly registered owner in the form
412	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the region code derived from the owner's
413	     * postcode (the same region derivation shared with {@link Owner#getLocality() locality}:
414	     * postcode range first, falling back to the city, or {@code 'UNKNOWN'}) and {@code HASH8} is the
415	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
416	     * concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Sequence numbers are not used,
417	     * so the code is a pure function of the owner's region and identity.
418	     *
419	     * @param owner the owner whose customer code is derived (with normalized telephone already set)
420	     * @return the assigned customer code
421	     */
422	    private String customerCode(Owner owner) {
423	        String region = owner.getLocality();
424	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
425	        return region + "-" + hash8;
426	    }
427	
428	    /**
429	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
430	     * UTF-8 bytes of {@code input}.
431	     *
432	     * @param input  the value to hash
433	     * @param length the number of leading hex characters to keep
434	     * @return the truncated, upper-cased hex digest
435	     */
436	    private String sha256UpperHex(String input, int length) {
437	        try {
438	            byte[] digest = MessageDigest.getInstance("SHA-256")
439	                .digest(input.getBytes(StandardCharsets.UTF_8));
440	            StringBuilder sb = new StringBuilder(digest.length * 2);
441	            for (byte b : digest) {
442	                sb.append(String.format("%02x", b));
443	            }
444	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
445	        }
446	        catch (java.security.NoSuchAlgorithmException e) {
447	            throw new IllegalStateException("SHA-256 not available", e);
448	        }
449	    }
450	
451	    /**
452	     * Rolls a registration date forward onto a business day. When the given date falls on a
453	     * Saturday or Sunday it is advanced to the following Monday; a weekday is returned unchanged.
454	     *
455	     * @param date the effective registration date (must not be {@code null})
456	     * @return the same date if it is a weekday, otherwise the next Monday
457	     */
458	    private LocalDate toBusinessDay(LocalDate date) {
459	        DayOfWeek dayOfWeek = date.getDayOfWeek();
460	        if (dayOfWeek == DayOfWeek.SATURDAY) {
461	            return date.plusDays(2);
462	        }
463	        if (dayOfWeek == DayOfWeek.SUNDAY) {
464	            return date.plusDays(1);
465	        }
466	        return date;
467	    }
468	
469	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
470	    @Override
471	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
472	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
473	        if (currentOwner == null) {
474	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
475	        }
476	        String email = ownerFieldsDto.getEmail();
477	        if (email != null) {
478	            email = normalizeEmail(email);
479	            if (!EMAIL_PATTERN.matcher(email).matches()) {
480	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
481	            }
482	        }
483	        String telephone = toE164(ownerFieldsDto.getTelephone());
484	        if (telephone == null) {
485	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
486	        }
487	        currentOwner.setAddress(ownerFieldsDto.getAddress());
488	        currentOwner.setCity(ownerFieldsDto.getCity());
489	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
490	        currentOwner.setLastName(ownerFieldsDto.getLastName());
491	        currentOwner.setTelephone(telephone);
492	        currentOwner.setEmail(email);
493	        this.clinicService.saveOwner(currentOwner);
494	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
495	    }
496	
497	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
498	    @Transactional
499	    @Override
500	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
501	        Owner owner = this.clinicService.findOwnerById(ownerId);
502	        if (owner == null) {
503	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
504	        }
505	        this.clinicService.deleteOwner(owner);
506	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
507	    }
508	
509	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
510	    @Override
511	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
512	        Owner owner = this.clinicService.findOwnerById(ownerId);
513	        if (owner == null) {
514	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
515	        }
516	        HttpHeaders headers = new HttpHeaders();
517	        Pet pet = petMapper.toPet(petFieldsDto);
518	        owner.setId(ownerId);
519	        pet.setOwner(owner);
520	        pet.getType().setName(null);
521	        this.clinicService.savePet(pet);
522	        PetDto petDto = petMapper.toPetDto(pet);
523	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
524	            .buildAndExpand(pet.getId()).toUri());
525	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
526	    }
527	
528	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
529	    @Override
530	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
531	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
532	        if (currentOwner != null) {
533	            Pet currentPet = this.clinicService.findPetById(petId);
534	            if (currentPet != null) {
535	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
536	                currentPet.setName(petFieldsDto.getName());
537	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
538	                this.clinicService.savePet(currentPet);
539	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
540	            }
541	        }
542	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
543	    }
544	
545	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
546	    @Override
547	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
548	        HttpHeaders headers = new HttpHeaders();
549	        Visit visit = visitMapper.toVisit(visitFieldsDto);
550	        Pet pet = new Pet();
551	        pet.setId(petId);
552	        visit.setPet(pet);
553	        this.clinicService.saveVisit(visit);
554	        VisitDto visitDto = visitMapper.toVisitDto(visit);
555	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
556	            .buildAndExpand(visit.getId()).toUri());
